NEW_FILES = {'migrations/migrate_bank_furnish.py': '#!/usr/bin/env python3\n"""\nmigrate_bank_furnish.py  --  a bank\'s lobby furnished as the comps, a vault\'s cash cart (0.281.0)\n================================================================================================\nOne-shot, idempotent migration over specs/*.json. Furnish gives a bank\'s public room the `bank_lobby` recipe -- a check\ndesk mid-floor, waiting chairs, an ATM, a queue; none of the general lobby\'s vending, cigarettes, payphone or sofa --\nand every `vault` room a cash cart beside its count table. The library is a fixed point of its furnishing pass, so\nevery spec with a room of either kind is refurnished (`migrate_furnish_recipes.migrate`); no other spec is touched.\n\n`lf_*` specs are Level Factory\'s per-run transients and are skipped.\n\n    python migrations/migrate_bank_furnish.py            # write specs/\n    python migrations/migrate_bank_furnish.py --check    # report only; exit 1 if any would change\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\nsys.path.insert(0, os.path.join(HERE, "migrations"))\n\nimport level_design  # noqa: E402\nimport migrate_furnish_recipes  # noqa: E402\n\nKINDS = ("bank_lobby", "bank_vault")\n\n\ndef _touched(d):\n    b = level_design.club_building_id(d)\n    return any(level_design._room_kind(r, b) in KINDS for r in d.get("rooms") or [])\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    root = os.path.join(HERE, "specs")\n    changed = 0\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not _touched(d):\n            continue\n        before = json.dumps(d, indent=1) + "\\n"\n        migrate_furnish_recipes.migrate(d)\n        after = json.dumps(d, indent=1) + "\\n"\n        if after == before:\n            continue\n        changed += 1\n        names = [str(v.get("name", "")) for v in d["volumes"]]\n        print(f"[bank_furnish] {os.path.basename(p)}: {sum(n.startswith(\'check_desk\') for n in names)} check desk(s), "\n              f"{sum(n.startswith(\'cash_cart\') for n in names)} cash cart(s)")\n        if not check:\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(after)\n    verb = "would change" if check else "refurnished"\n    print(f"[bank_furnish] {changed} spec(s) {verb}")\n    return 1 if check and changed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_bank_furnish.py': '"""A bank\'s lobby is furnished as the walker\'s comps, and a bank\'s vault keeps a cash cart (0.281.0, roadmap 321).\n\nThe comps (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md): the teller line is the room, "a check desk island\nstands mid-floor in front of it", a queue of stanchions, waiting chairs; the money room\'s "steel cage cart". Measured\nbefore (docs/findings/bank_interior/): bank_branch_a02\'s 390 m2 lobby stood a bench, two bins and a queue, and the\ngeneral lobby recipe a bank shared with a hotel handed it vending, cigarettes, a payphone and a sofa.\n\nFAILS ON 0.280.0: there is no `bank_lobby` or `bank_vault` kind, no check desk and no cash cart.\n"""\nimport glob\nimport json\nimport os\n\nimport level_design\nimport prop_species\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nBANKS = ("bank_branch_a02", "bank_branch_a03", "bank_branch_a04", "bank_job", "bank_tower_a01", "bank_tower_a02",\n         "bank_tower_a03")\nNOT_IN_A_BANK = ("vending", "cigarettes", "payphone", "sofa")\n\n\ndef test_a_banks_public_room_and_vault_are_their_own_kinds_and_no_one_elses():\n    lobby = {"id": "lobby", "role": "public_entry", "story": 0}\n    vault = {"id": "vault_west", "role": "fortifiable", "story": -1}\n    assert level_design._room_kind(lobby, "bank_branch_a02") == "bank_lobby"\n    assert level_design._room_kind(lobby, "hotel_a01") == "lobby"\n    assert level_design._room_kind(vault, "bank_job") == "bank_vault"\n    assert level_design._room_kind(vault, "deli_a01") == "vault"           # the control: a deli\'s back safe\n\n\ndef test_the_bank_lobby_recipe_stands_a_check_desk_and_none_of_the_general_lobbys_extras():\n    r = level_design._RECIPES["bank_lobby"]\n    assert "check_desk" in r["anchors"]\n    named = set(r["anchors"]) | set(r["wall"]) | set(r["floor"]) | {p for c in r["clusters"] for p in c[0]}\n    assert not named & set(NOT_IN_A_BANK), named\n    assert "cash_cart" in level_design._RECIPES["bank_vault"]["floor"]\n    assert "cash_cart" not in level_design._RECIPES["vault"]["floor"]\n\n\ndef test_the_pieces_route_to_zoos_species():\n    assert prop_species.species_for_name("check_desk_rcce455f7_1") == "check_desk"\n    assert prop_species.species_for_name("cash_cart_r3a1da818_6") == "cash_cart"\n\n\ndef _spec(name):\n    return json.load(open(os.path.join(HERE, "specs", name + ".json"), encoding="utf-8"))\n\n\ndef _in(v, room):\n    x0, y0, x1, y1 = room["bounds"]\n    return x0 <= v.get("x", 1e9) <= x1 and y0 <= v.get("y", 1e9) <= y1\n\n\ndef test_every_library_bank_has_its_check_desk_and_carts_and_no_lobby_extras():\n    for name in BANKS:\n        d = _spec(name)\n        b = level_design.club_building_id(d)\n        lobbies = [r for r in d["rooms"] if level_design._room_kind(r, b) == "bank_lobby"]\n        vaults = [r for r in d["rooms"] if level_design._room_kind(r, b) == "bank_vault"]\n        assert lobbies and vaults, name\n        vols = d["volumes"]\n        assert any(v["name"].startswith("check_desk") for v in vols), name\n        assert any(v["name"].startswith("cash_cart") for v in vols), name\n        for r in lobbies:\n            story = int(r.get("story", 0) or 0)\n            extras = [v["name"] for v in vols if _in(v, r) and v["name"].startswith(NOT_IN_A_BANK)\n                      and level_design._volume_story(d, v) == story]\n            assert not extras, (name, r["id"], extras)\n\n\ndef test_no_other_building_has_either():\n    for p in sorted(glob.glob(os.path.join(HERE, "specs", "*.json"))):\n        n = os.path.basename(p)[:-5]\n        if n.startswith("lf_") or n in BANKS:\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        names = [str(v.get("name", "")) for v in d.get("volumes") or []]\n        assert not any(x.startswith(("check_desk", "cash_cart")) for x in names), n\n'}
CHANGELOG = '## [0.281.0] - a bank\'s lobby furnished as the comps, and a bank\'s vault keeps a cash cart\n\nThe walker\'s bank comps (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md): the teller line is the room, and "a\ncheck desk island stands mid-floor in front of it". There is a queue of stanchions and waiting chairs, and the money\nroom has its "steel cage cart". Measured on bank_branch_a02 after 0.280.0 lit and floored it\n(docs/findings/bank_interior/): its 390 m2 lobby stood a bench, two bins and a queue. The general lobby recipe a bank\nshared with a hotel handed it vending, cigarettes, a payphone and a sofa. Zoo 1.135.0 draws the desk and the cart.\n\n### Added\n- **`check_desk`**, a piece: an island at standing height (1.1 m, below cover height), 1.6 or 2.4 m long, two a room\n  at most. Zoo\'s `check_desk`, its date block on its middle.\n- **`cash_cart`**, a piece: on the floor, 1.2 or 0.9 m long, its load the variant, two a room at most. Zoo\'s\n  `cash_cart`.\n- **`bank_lobby`**, a kind and its recipe, for a bank\'s public room (`is_bank_lobby`, `lights.bank_public`, the rule\n  0.280.0 lit and floored by):\n  - the check desk its anchor;\n  - waiting chairs and an ATM on the walls;\n  - a queue of stanchions and a bin;\n  - no vending, cigarettes, payphone or sofa.\n- **`bank_vault`**, a kind and its recipe, for a bank\'s vault (`_room_kind` wraps `_room_kind_of`): the vault\'s\n  furniture and a cash cart beside the count table.\n  - A BANK\'S only. The first build put a cart in every `vault`-kind room and moved 44 specs: a deli\'s back safe, a\n    stadium\'s, a funeral home\'s.\n  - It keeps the vault\'s exemption from the basement clutter.\n- `prop_species` routes both, ahead of the box row whose `cart` would make the cart a grey box.\n- **`migrations/migrate_bank_furnish.py`** refurnishes the seven banks:\n  - each lobby gets its check desk;\n  - the vaults get 1-5 cash carts a building;\n  - no other spec changes.\n\n### Tests\n- `tests/test_bank_furnish.py` (4 of 5 fail on 0.280.0; the fifth holds that no other building has either):\n  - a bank\'s lobby and vault are their own kinds, and a hotel\'s lobby and a deli\'s vault are not (the controls);\n  - the bank lobby recipe stands a check desk and none of the general lobby\'s extras;\n  - the pieces route to Zoo\'s species;\n  - every library bank has its check desk and carts, and no lobby extras.\n- `test_furnish`:\n  - names the bank lobby among the recipes that stand an island;\n  - mirrors both species\' sizes.\n- Three tests held the old bank lobby, and say the new one:\n  - `test_club_fixtures`: a bank\'s lobby stands no cigarette machine and a hotel\'s keeps one; the library\'s count is\n    71 -> 64, the seven banks.\n  - `test_payphone_wall_form`: 39 -> 32 payphones, the seven banks\' lobbies.\n  - `test_ticket_queue`: bank_job\'s lobby is known by its ATM and check desk, not its payphone and sofa.\n  - The first apply of this release stopped in the suite on all five. Only the furnish tests had been run on the\n    clone; the whole suite now runs there first.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.280.0', 'Deli Counter 0.281.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
